import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {sourcePrefixHash} from '../live-paper/native-journal-restore.mjs';import {sha} from '../live-paper/native-dip-proof-v1.mjs';import {atomicJson} from '../execution/ledger.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),read=f=>JSON.parse(fs.readFileSync(f)),mode=process.argv[2],file='data/native-quote-preservation-20261004.json';assert(['before','after'].includes(mode));const prior=mode==='after'?read(file):null,banks={},sources={},identities={};
for(const type of ['baal-pair','no-maker','probability-receipt']){const activeFile=path.join(r,type+'-active.json'),active=read(activeFile),dir=path.join(r,type+'-cohorts',active.cohort),journal=path.join(dir,'journal.jsonl'),bytes=fs.statSync(journal).size,x={cohort:active.cohort,activeHash:sha(fs.readFileSync(activeFile)),bankHash:sha(fs.readFileSync(path.join(dir,'bank.json'))),journalBytes:bytes,journalPrefixHash:await sourcePrefixHash(journal,bytes)};if(prior){const old=prior.banks[type];assert.equal(x.activeHash,old.activeHash);assert.equal(x.bankHash,old.bankHash);assert(bytes>=old.journalBytes);assert.equal(await sourcePrefixHash(journal,old.journalBytes),old.journalPrefixHash);}banks[type]=x;}
for(const name of ['native-dip-active.json','native-dip-cache-active.json','native-dip-intent-active.json','native-quote-active.json','coordinated-network-budget.json','competition-activation.json']){const hash=sha(fs.readFileSync(path.join(r,name)));if(prior)assert.equal(hash,prior.identities[name]);identities[name]=hash;}
for(const name of ['journal.jsonl','public-books.jsonl','market-prices.jsonl','account-eligibility.jsonl']){const file=path.join(r,name),bytes=fs.statSync(file).size,hash=bytes?await sourcePrefixHash(file,bytes):sha('');if(prior){const old=prior.sources[name];assert(bytes>=old.bytes);assert.equal(old.bytes?await sourcePrefixHash(file,old.bytes):sha(''),old.hash);}sources[name]={bytes,hash};}
const evidence={schemaVersion:1,at:new Date().toISOString(),mode,banks,sources,identities,frozenBanksPreserved:true,originalJournalsPreserved:true,competitionOrders:0};atomicJson(mode==='before'?file:'data/native-quote-preservation-after-20261004.json',evidence);console.log(JSON.stringify({mode,banks:Object.keys(banks),sources:Object.keys(sources),preserved:true}));
